pub fn is_prime(n: i8) -> bool {
    if n < 2 {
        return false;
    }

    // Use i16 for safe arithmetic (avoid overflow when computing bounds).
    let nn = n as i16;
    let mut k: i16 = 2;

    // Check divisors in [2, n). If any divides n, it's not prime.
    while k < nn {
        if nn % k == 0 {
            return false;
        }
        k += 1;
    }

    true
}